#!/usr/bin/env node
/**
 * Builds lib/legal/content.generated.ts from the markdown in store/:
 *   store/privacy-policy.md  → the /privacy page
 *   store/delete-account.md  → the /delete-account page
 * filling the [bracket] placeholders from store/legal-details.json.
 *
 *   npm run legal          rebuild after editing any of those files
 *   npm run legal:check    fail if the generated file is out of date
 */
const fs = require('fs')
const path = require('path')

const root = path.join(__dirname, '..')
const read = f => fs.readFileSync(path.join(root, f), 'utf8')
const OUT = 'lib/legal/content.generated.ts'

// legal-details.json key → the exact placeholder text used in the markdown.
const PLACEHOLDERS = {
  yourName: '[your name]',
  contactEmail: '[contact email]',
  country: '[country]',
  supabaseRegion: '[Supabase region, e.g. EU (Frankfurt)]',
  backupDays: '[number of days, e.g. 7 days]',
  dataProtectionAuthority: "[your country's authority, e.g. IMY in Sweden]",
  effectiveDate: '[date]',
}

function fill(md, details) {
  let out = md
  for (const [key, placeholder] of Object.entries(PLACEHOLDERS)) {
    const value = String(details[key] ?? '').trim()
    if (!value) continue
    // An email becomes a mailto link so it's tappable on the page.
    const replacement = key === 'contactEmail' ? `[${value}](mailto:${value})` : value
    out = out.split(placeholder).join(replacement)
  }
  return out
}

function build() {
  const details = JSON.parse(read('store/legal-details.json'))
  const privacy = fill(read('store/privacy-policy.md'), details)
  const deletion = fill(read('store/delete-account.md'), details)
  const missing = Object.entries(PLACEHOLDERS)
    .filter(([key]) => !String(details[key] ?? '').trim())
    .map(([key]) => key)
  return [
    '// Generated by scripts/build-legal.js from store/*.md. Do not edit:',
    '// edit the markdown or store/legal-details.json, then run `npm run legal`.',
    '',
    `export const privacyPolicyMarkdown = ${JSON.stringify(privacy)}`,
    '',
    `export const deleteAccountMarkdown = ${JSON.stringify(deletion)}`,
    '',
    '/** Details in store/legal-details.json that are still empty. */',
    `export const missingLegalDetails: string[] = ${JSON.stringify(missing)}`,
    '',
  ].join('\n')
}

const content = build()
const outPath = path.join(root, OUT)
if (process.argv.includes('--check')) {
  const current = fs.existsSync(outPath) ? fs.readFileSync(outPath, 'utf8') : ''
  if (current !== content) {
    console.error(`${OUT} is out of date. Run \`npm run legal\` and commit the result.`)
    process.exit(1)
  }
  console.log(`${OUT} is up to date.`)
} else {
  fs.mkdirSync(path.dirname(outPath), { recursive: true })
  fs.writeFileSync(outPath, content)
  const missing = JSON.parse(content.match(/missingLegalDetails: string\[\] = (.*)/)[1])
  console.log(`Wrote ${OUT}.`)
  if (missing.length) console.log(`Still empty in store/legal-details.json: ${missing.join(', ')}`)
}
